css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .74); position: relative; }
.loader::before { content: ''; position: absolute; z-index: 2; top: 10%; left: 0; width: 100%; height: 18%; border-bottom: calc(var(--loader-size) * .022) solid color-mix(in srgb, #000 42%, var(--accent-2)); border-radius: 0 0 50% 50% / 0 0 100% 100%; }
.loader span { position: absolute; width: 19%; height: 44%; transform-origin: top center; background: linear-gradient(var(--accent), var(--accent-2)); animation: sway calc(var(--loader-speed) * 2.2) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; z-index: 3; bottom: 97%; left: 38%; width: 24%; height: calc(var(--loader-size) * .055); border-radius: 2px; background: color-mix(in srgb, #000 26%, var(--accent-2)); }
.loader span:nth-child(1) { left: 4%; top: 25%; border-radius: 3px 3px 40% 8%; }
.loader span:nth-child(2) { left: 28%; top: 30%; border-radius: 3px 3px 8% 40%; animation-delay: calc(var(--loader-speed) * .16); }
.loader span:nth-child(3) { left: 52%; top: 30%; border-radius: 3px 3px 40% 8%; animation-delay: calc(var(--loader-speed) * .32); }
.loader span:nth-child(4) { left: 76%; top: 25%; border-radius: 3px 3px 8% 40%; animation-delay: calc(var(--loader-speed) * .48); }
@keyframes sway { 0%, 100% { transform: rotate(-9deg); } 50% { transform: rotate(9deg); } }
